import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"CI/CD and release-chain gates (maintainer guide)","description":"","frontmatter":{},"headers":[],"relativePath":"release/ci-gates.md","filePath":"release/ci-gates.md"}'),i={name:"release/ci-gates.md"};function n(r,e,c,l,d,h){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="ci-cd-and-release-chain-gates-maintainer-guide" tabindex="-1">CI/CD and release-chain gates (maintainer guide) <a class="header-anchor" href="#ci-cd-and-release-chain-gates-maintainer-guide" aria-label="Permalink to &quot;CI/CD and release-chain gates (maintainer guide)&quot;">​</a></h1><p>What <code>.github/workflows/build.yml</code> enforces on every push, what the release chain checks before a tag may move, and how the regression floor is enforced. Companion pages: <a href="./process.html">process</a> (the SOP these gates hang on), <a href="./build-reference.html">build-reference</a> (the pipeline CI builds), <a href="./guard-scripts.html">guard-scripts</a> (the static guards).</p><h2 id="_1-the-workflow-—-shape-and-provenance" tabindex="-1">1. The workflow — shape and provenance <a class="header-anchor" href="#_1-the-workflow-—-shape-and-provenance" aria-label="Permalink to &quot;1. The workflow — shape and provenance&quot;">​</a></h2><p><code>.github/workflows/build.yml</code> is the repo&#39;s single CI workflow:</p><ul><li><strong>Name</strong> <code>build</code>; <strong>triggers</strong>: push to <code>main</code>, PR to <code>main</code>, <code>workflow_dispatch</code>; <strong>permissions</strong>: <code>contents: read</code>; one job <code>3.0.0 build (0-warning gate)</code> on <code>ubuntu-latest</code>, <code>timeout-minutes: 40</code>.</li><li><strong>Honest provenance note</strong> (declared in the file header): the 3.0.0 mainline had NO CI workflow at its last mainline commit — nothing to restore. This file is NEW WP00 infrastructure so &quot;CI green&quot; remains an enforceable gate. <strong>It builds; it does not boot</strong> — every QEMU run is a sandbox-only acceptance step.</li><li>Why build-only CI is acceptable here: the zero-warning gate plus the deterministic build catch most regressions mechanically, and the boot/E2E matrix (§5) runs in the release sandbox via <code>tools/build_release.sh --deep</code>. The process compensates with a hard rule: <strong>the tag must point at a CI-green commit — never tag a red commit</strong> (see <a href="./process.html">process</a> step 5).</li></ul><h2 id="_2-the-six-ci-steps-one-by-one" tabindex="-1">2. The six CI steps, one by one <a class="header-anchor" href="#_2-the-six-ci-steps-one-by-one" aria-label="Permalink to &quot;2. The six CI steps, one by one&quot;">​</a></h2><h3 id="step-1-—-checkout-with-fetch-depth-0" tabindex="-1">Step 1 — Checkout with <code>fetch-depth: 0</code> <a class="header-anchor" href="#step-1-—-checkout-with-fetch-depth-0" aria-label="Permalink to &quot;Step 1 — Checkout with \`fetch-depth: 0\`&quot;">​</a></h3><p><code>actions/checkout@v4</code> with full history. <strong>Mandatory, not cosmetic</strong>: the build id is <code>git rev-list --count HEAD + 21</code> (the <code>Makefile</code><code>OC_KERNEL_BUILD</code> derivation), and the OTA update check compares build ids NUMERICALLY (BUG-0347: remote &gt; local only). A shallow clone would bake a build id far BELOW the published ones (278/321/414/416), and every installed machine would silently ignore the release as a &quot;downgrade&quot;. A wrong-but-green CI build is worse than no build at all — hence full depth is step zero.</p><h3 id="step-2-—-install-toolchain" tabindex="-1">Step 2 — Install toolchain <a class="header-anchor" href="#step-2-—-install-toolchain" aria-label="Permalink to &quot;Step 2 — Install toolchain&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt-get install -y -qq build-essential nasm xorriso mtools \\</span></span>
<span class="line"><span>  grub-pc-bin grub-efi-amd64-bin grub-common</span></span></code></pre></div><p>Exactly the package set <code>tools/build.sh</code> probes for (plus build-essential for gcc/ld). Missing any of them fails the next step with the compiler/packer&#39;s own error.</p><h3 id="step-3-—-select-compiler-prefer-gcc-14" tabindex="-1">Step 3 — Select compiler (prefer gcc-14) <a class="header-anchor" href="#step-3-—-select-compiler-prefer-gcc-14" aria-label="Permalink to &quot;Step 3 — Select compiler (prefer gcc-14)&quot;">​</a></h3><p>Install <code>gcc-14</code> (best effort, <code>|| true</code>), then emit <code>cc=gcc-14</code> when <code>command -v gcc-14</code> succeeds, else <code>cc=gcc</code>. gcc-14 is the release compiler (Debian gcc 14.2.0 — the compiler the release builds have always used); the fallback keeps the workflow from hard-failing on runner image changes, at the cost of a slightly different codegen — which is itself caught by the artifact assertions in step 5.</p><h3 id="step-4-—-build-make-all-—-the-ci-lint" tabindex="-1">Step 4 — Build (<code>make all</code>) — the CI &quot;lint&quot; <a class="header-anchor" href="#step-4-—-build-make-all-—-the-ci-lint" aria-label="Permalink to &quot;Step 4 — Build (\`make all\`) — the CI &quot;lint&quot;&quot;">​</a></h3><p><code>make all CC=\${{ steps.cc.outputs.cc }}</code> runs the full WP-13 pipeline: userprogs → kernel (two-stage link) → dual-firmware OCBL ISO → deterministic src zip → OTA package. The lint IS the build: every component Makefile (kernel, OCIRE, OCBL, OCSE, agent) carries <code>-Wall -Wextra -Werror</code>, so any warning anywhere fails <code>make</code> with the compiler&#39;s diagnostic and a non-zero exit. This is the gate that caught the 2.0.0-era &quot;compiles locally but not on CI&quot; class (the tui_core.c port-constraint P0) — which is why the SOP demands 0-warning on BOTH the local toolchain and the runner.</p><h3 id="step-5-—-verify-artifacts" tabindex="-1">Step 5 — Verify artifacts <a class="header-anchor" href="#step-5-—-verify-artifacts" aria-label="Permalink to &quot;Step 5 — Verify artifacts&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>file build/opencube.elf            → grep &#39;ELF 64-bit&#39;</span></span>
<span class="line"><span>file build/opencube.iso            → grep &#39;ISO 9660&#39;</span></span>
<span class="line"><span>test -s build/opencube.elf         (non-empty)</span></span>
<span class="line"><span>test -s build/opencube.iso</span></span>
<span class="line"><span>xorriso -indev ... -report_el_torito plain</span></span>
<span class="line"><span>  → grep &#39;El Torito boot img : 1 BIOS y none&#39;</span></span>
<span class="line"><span>  → grep &#39;El Torito boot img : 2 UEFI y none&#39;</span></span>
<span class="line"><span>test -s dist/OpenCubeOS-src-3.0.0-NAK.zip</span></span>
<span class="line"><span>test -s dist/OpenCubeOS-3.0.0-NAK-update.tar.gz</span></span></code></pre></div><p><strong>The three hard assertions</strong> (each greps the real artifact, so a wrongly-shaped product cannot pass):</p><ol><li><strong>Type assertions</strong> — the ELF must be <code>ELF 64-bit</code> and the ISO must be <code>ISO 9660</code>, and both must be non-empty. A truncated or mis-linked product fails here.</li><li><strong>Dual-firmware El Torito assertion</strong> — the xorriso report must show BOTH <code>El Torito boot img : 1 BIOS y none</code> AND <code>: 2 UEFI y none</code>. This is the machine check that the same ISO carries the BIOS and the UEFI boot images (the OCBL dual-firmware promise); a BIOS-only or UEFI-only ISO fails here even though it &quot;built fine&quot;.</li><li><strong>Completeness assertion</strong> — the src zip and the OTA tar.gz must exist and be non-empty (the pipeline did not silently skip a leg).</li></ol><h3 id="step-6-—-verify-make-clean-leaves-no-products" tabindex="-1">Step 6 — Verify <code>make clean</code> leaves no products <a class="header-anchor" href="#step-6-—-verify-make-clean-leaves-no-products" aria-label="Permalink to &quot;Step 6 — Verify \`make clean\` leaves no products&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make clean</span></span>
<span class="line"><span>left=$(find build dist -type f 2&gt;/dev/null | wc -l)</span></span>
<span class="line"><span>test &quot;$left&quot; -eq 0</span></span></code></pre></div><p>Zero files may remain under <code>build dist</code>. This catches rule-hygiene regressions: artifacts written outside <code>$(BUILD)</code>/<code>$(DIST)</code>, or files the clean rule forgot, would leave <code>left &gt; 0</code> and fail the step.</p><h2 id="_3-what-ci-does-not-run-and-where-those-gates-live-instead" tabindex="-1">3. What CI does NOT run (and where those gates live instead) <a class="header-anchor" href="#_3-what-ci-does-not-run-and-where-those-gates-live-instead" aria-label="Permalink to &quot;3. What CI does NOT run (and where those gates live instead)&quot;">​</a></h2><p><code>make test</code> (host unit harnesses), every QEMU boot, the 31-check regression, and the E2E suites never run in CI. They are release-time gates in the sandbox:</p><ul><li><code>tools/build_release.sh &lt;ver&gt; --deep</code> (SOP steps 1–5: clean build → reproducible-check → BIOS+UEFI boot banner gates → deep gates → docs/website data) — the boot gates grep a FRESH mktemp log per run (BUG #63 fix: the old fixed <code>/tmp/rel_boot.log</code> let a stale log satisfy the greps — a fake green).</li><li>The verification matrix (<code>make test</code>, <code>run_fix4_regression.py</code> 31/31, <code>ssh_g11a_e2e.py</code> 5 checks, <code>run_fix4_https_e2e.py</code> 8 checks, <code>wp12_watchdog_logging_e2e.py</code> S1–S14, the <code>wp10_*</code> suites, the mega-app smoke 21/21) — see <a href="./tool-inventory.html">tool-inventory</a> for the tools and <a href="./process.html">process</a> step 4 for the matrix.</li></ul><h2 id="_4-the-release-chain-—-the-12-point-check-item-by-item" tabindex="-1">4. The release chain — the 12-point check, item by item <a class="header-anchor" href="#_4-the-release-chain-—-the-12-point-check-item-by-item" aria-label="Permalink to &quot;4. The release chain — the 12-point check, item by item&quot;">​</a></h2><p>Run after the assets are live (from <a href="./process.html">process</a> §8). Every item is a pass/fail question with a concrete verification action:</p><ol><li><strong>Both repos&#39; remote HEADs match local</strong> — <code>git ls-remote</code> on the public repo and the private mirror shows the expected SHAs (the push actually landed, nowhere is half-updated).</li><li><strong>The tag exists on the public repo and points at a CI-green commit</strong> — the Actions run for that exact SHA is green; never tag a red commit.</li><li><strong>Author identity on every release commit</strong> — <code>cubestudio-dev &lt;cubestudio@qq.com&gt;</code>; <code>build_release.sh</code> refuses to start otherwise.</li><li><strong>gh-pages updated</strong> — the live site serves the new version (fetch the site, check the version marker).</li><li><strong><code>update.json</code> consistency (both copies)</strong> — version + build + <code>package_sha256</code> present, and the two copies (website/ top level AND <code>website/public/</code>) are byte-identical.</li><li><strong>Three-way asset hashes</strong> — see §5 below.</li><li><strong>Website numbers regenerated from <code>docs/data/*.json</code></strong> — the commands/interfaces/lines counters match the freshly generated JSON, never a copied stale block (the 2.0.0 site shipped a stale 130,011 line count that way).</li><li><strong>The step-4 gates all green</strong> — paste the real outputs into the release evidence, skip counts declared.</li><li><strong>Token hygiene</strong> — only the last 4 characters of any token ever appear in logs/reports.</li><li><strong>Whole-repo number consistency</strong> — the command-home / category / L1SVC-op / syscall counts and the stats.json line count are recomputed every release, never carried over.</li><li><strong>Private mirror complete</strong> — the three assets + release note + mirrored website files are in the mirror (the mirror rules are maintained by the maintainers outside the public docs).</li><li><strong>CI green on the release commit AND on the tagged commit</strong> — the same SHA checked twice, because a tag can move.</li></ol><h2 id="_5-sha256-three-way-verification" tabindex="-1">5. SHA256 three-way verification <a class="header-anchor" href="#_5-sha256-three-way-verification" aria-label="Permalink to &quot;5. SHA256 three-way verification&quot;">​</a></h2><p>The release note publishes the SHA256 of each of the three assets (ISO, src zip, OTA tar.gz). The check proves the SAME bytes reached every channel:</p><ol><li><strong>Local</strong>: <code>sha256sum</code> over the three <code>dist/</code>/<code>build/</code> artifacts (<code>build_release.sh</code> prints them at the end of a gated run).</li><li><strong>Release API</strong>: fetch the GitHub Release asset metadata via the API and compare the digest the platform computed on upload — this catches truncated or wrong-version uploads.</li><li><strong>Live download</strong>: download the asset from the public URL a user would use and hash it again — this catches CDN/cache/redirect drift between the Release object and what users actually get.</li></ol><p>All three must be equal for each asset. The same discipline extends to <code>update.json</code> (the OTA manifest carries <code>package_sha256</code>, so the kernel&#39;s own updater re-verifies at install time) and to the site (<code>website/public/update.json</code> byte-identical with <code>website/update.json</code>).</p><h2 id="_6-the-regression-floor-276-minimum-284-measured" tabindex="-1">6. The regression floor: 276 minimum, 284 measured <a class="header-anchor" href="#_6-the-regression-floor-276-minimum-284-measured" aria-label="Permalink to &quot;6. The regression floor: 276 minimum, 284 measured&quot;">​</a></h2><p><code>tools/run_fix4_regression.py</code> boots the built ISO (512M, <code>-serial mon:stdio</code>, e1000 user-net, an HMP monitor unix socket for the framebuffer assertion), waits for <code>ush&gt;</code>, runs 24 commands, and scores <strong>31 checks</strong>; the exit code equals the number of failed checks (the release matrix quotes 31/31).</p><p>The command-count check (check 6 of 31) is the <strong>interface-freeze floor</strong>:</p><ul><li><strong>Logic</strong>: the count is measured dynamically from the <code>help -a</code> registry listing (two-space-indented <code>name [tag] description</code> rows) — never a stale literal (the old gate grepped <code>Total: 233 commands.</code>, a string that no longer exists in the output at all).</li><li><strong>Floor</strong>: <code>n &gt;= 276</code>. 276 = the g3 baseline (275) + p0leak (the WP-fix-critical-security P0 fence probe that rides the gate so every future release re-proves it).</li><li><strong>Current measurement</strong>: 284 commands on the WP-l1apps-merge tree — the floor is 8 under the measured surface, so adding commands is always fine and removing even one fails the gate.</li><li><strong>Rule behind it</strong>: commands may be ADDED, never removed. When the measured count rises permanently, the floor literal is raised in the same commit that adds the commands (never before).</li></ul><p>Anti-fake-green mechanics baked into the same gate (why the floor cannot be satisfied by accident):</p><ul><li>Every pattern is scoped to ONE command&#39;s output section (BUG #64 fix: patterns used to match the WHOLE combined log, so command echoes satisfied name-bearing patterns and any PASS anywhere satisfied every check — the gate was structurally always-true).</li><li>The echoed command line is stripped before matching.</li><li>The framebuffer check requires an HMP screendump with ≥ 2 colors and a measurable foreground ratio (BUG #66).</li><li>The <code>g6_test</code> async tally gets its own 300-second wait window.</li></ul><h2 id="_7-build-release-sh-—-the-gated-front-door" tabindex="-1">7. build_release.sh — the gated front door <a class="header-anchor" href="#_7-build-release-sh-—-the-gated-front-door" aria-label="Permalink to &quot;7. build_release.sh — the gated front door&quot;">​</a></h2><p><code>tools/build_release.sh &lt;version&gt; [--deep]</code> automates SOP steps 1–5 and refuses to run when: the tag <code>&lt;version&gt;</code> already exists, or the git identity is not <code>cubestudio-dev</code>. Sequence: clean <code>make -j all</code> (0-warning gate) → <code>make reproducible-check</code> → BIOS boot gate → UEFI boot gate (pflash CODE + writable VARS copy; the plain <code>-bios</code> form silently fails to run the payload on current OVMF builds) → optional <code>--deep</code> gates (<code>run_fix4_regression.py</code>, <code>wp12_watchdog_logging_e2e.py</code>) → <code>gen_api_docs.py --pages --pages-zh --md</code> + <code>update_website.sh</code> + <code>website/build.sh</code> → prints the three SHA256s. It pushes NOTHING — review the outputs, then run the release chain manually (deliberate asymmetry; the push-channel runbook is maintained by the maintainers outside the public docs).</p><p>The older <code>tools/github_release_wp08.sh</code> (WP-08 era) pushes commit+tag and creates the Release with the ISO asset via the API (<code>GITHUB_TOKEN</code> with repo + workflow scopes) — retained for history; the modern flow creates the Release by hand from the gated artifacts.</p>`,41)])])}const g=t(i,[["render",n]]);export{u as __pageData,g as default};
